sections.markdown:
**Think of Retrofit as the automatic secretary that turns your written instructions into typed API calls.**

Dio is the FedEx pickup truck. Retrofit is the office manager who reads your endpoint spec (`GET /users/{id}`), fills the forms, drives to FedEx, and returns a typed `User` object — without you writing the plumbing.

You describe the API in a Dart abstract class with annotations:

```
@RestApi(baseUrl: 'https://api.example.com')
abstract class ApiClient {
  factory ApiClient(Dio dio) = _ApiClient;
  @GET('/users/{id}') Future<User> user(@Path() int id);
  @POST('/orders') Future<Order> create(@Body() Order o);
}
```

`build_runner` reads the annotations + generates `_ApiClient` — a concrete class that calls Dio under the hood, serializes with `json_serializable`, returns typed `User` / `Order`. **No runtime reflection** (Dart forbids it in AOT); everything is codegen at build time.

**Why every serious Flutter team eventually reaches for it:** hand-written API clients drift from the OpenAPI spec, forget to encode a query param, break on schema changes, and duplicate the same `dio.get(...).then(User.fromJson)` boilerplate across 40 endpoints. Retrofit + json_serializable turns the client into declarative *description*, not imperative code. Refactors are trivial: rename a field in the model, regen, compile errors point you at every affected call site.

sections.code:
// pubspec.yaml:
//   dio: ^5.4.0
//   retrofit: ^4.1.0
//   json_annotation: ^4.9.0
// dev_dependencies:
//   retrofit_generator: ^8.0.0
//   json_serializable: ^6.7.1
//   build_runner: ^2.4.8

// ────── models/user.dart ──────
import 'package:json_annotation/json_annotation.dart';
part 'user.g.dart';

@JsonSerializable()
class User {
  final int id;
  final String name;
  final String? email;
  const User({required this.id, required this.name, this.email});
  factory User.fromJson(Map<String, dynamic> j) => _$UserFromJson(j);
  Map<String, dynamic> toJson() => _$UserToJson(this);
}

// ────── api/api_client.dart ──────
import 'package:dio/dio.dart';
import 'package:retrofit/retrofit.dart';
import '../models/user.dart';
part 'api_client.g.dart';

@RestApi(baseUrl: 'https://api.example.com')
abstract class ApiClient {
  factory ApiClient(Dio dio, {String? baseUrl}) = _ApiClient;

  @GET('/users')
  Future<List<User>> listUsers({@Query('page') int page = 1, @Query('q') String? q});

  @GET('/users/{id}')
  Future<User> user(@Path() int id, {@CancelRequest() CancelToken? cancel});

  @POST('/users')
  Future<User> create(@Body() User u,
      {@Header('Idempotency-Key') required String key});

  @PATCH('/users/{id}')
  Future<User> update(@Path() int id, @Body() Map<String,dynamic> patch);

  @DELETE('/users/{id}')
  Future<void> delete(@Path() int id);

  @POST('/avatar')
  @MultiPart()
  Future<void> uploadAvatar(@Part(name: 'file') File file,
    {@SendProgress() ProgressCallback? onSendProgress,
     @CancelRequest() CancelToken? cancel});

  @POST('/login')
  @FormUrlEncoded()
  Future<AuthTokens> login(@Field() String username, @Field() String password);
}

// ────── wire up ──────
final dio = createProductionDio(baseUrl: 'https://api.example.com');
final api = ApiClient(dio);

final user = await api.user(42);        // typed User
final users = await api.listUsers(page: 2, q: 'Ada');

// generate:
// dart run build_runner build --delete-conflicting-outputs
// or continuous:
// dart run build_runner watch --delete-conflicting-outputs

// api_client.g.dart (simplified)
class _ApiClient implements ApiClient {
  _ApiClient(this._dio, {this.baseUrl}) { baseUrl ??= 'https://api.example.com'; }
  final Dio _dio;
  String? baseUrl;

  @override
  Future<User> user(int id, {CancelToken? cancel}) async {
    final res = await _dio.fetch<Map<String, dynamic>>(Options(method: 'GET')
        .compose(_dio.options, '/users/$id', cancelToken: cancel));
    return User.fromJson(res.data!);
  }

  @override
  Future<List<User>> listUsers({int page = 1, String? q}) async {
    final res = await _dio.fetch<List<dynamic>>(Options(method: 'GET')
        .compose(_dio.options, '/users', queryParameters: {'page': page, if (q != null) 'q': q}));
    return res.data!.map((e) => User.fromJson(e as Map<String, dynamic>)).toList();
  }
  // ... etc — one method per annotated declaration.
}
